state.isCameraRunning=true;state.isScanning=false;disarmFirstGestureCameraStart();await syncTorchSupport();if(!state.capturePageOpen||generation!==state.captureGeneration||document.hidden||!state.track){throw new DOMException("Capture closed","AbortError");}
